// app/javascript/controllers/address_search_controller.js
var address_search_controller_default = class extends Controller {
  static targets = ["input", "intervention", "interventionList", "interventionItem", "address", "suggestions"];
  connect() {
    this.baseUrl = "https://nominatim.openstreetmap.org/search";
    this.timeout = null;
    this.previousQuery = "";
  }
  onInput() {
    const query = this.inputTarget.value.trim();
    if (query.length >= 3 && query !== this.previousQuery) {
      this.previousQuery = query;
      clearTimeout(this.timeout);
      this.timeout = setTimeout(() => {
        this.fetchSuggestions(query);
      }, 300);
    } else if (query.length < 3) {
      this.clearSuggestions();
    }
  }
  onFocus(event) {
    this.interventionListTarget.style.display = "block";
  }
  onBlur(event) {
    setTimeout(() => {
      this.interventionListTarget.style.display = "none";
    }, 300);
  }
  fetchSuggestions(query) {
    const url = `${this.baseUrl}?q=${encodeURIComponent(query)}&format=json&addressdetails=1&limit=5&countrycodes=FR`;
    fetch(url).then((response) => response.json()).then((data) => this.updateSuggestions(data)).catch((error2) => {
      console.error("Error fetching suggestions: ", error2);
      this.clearSuggestions();
    });
  }
  updateSuggestions(results) {
    const suggestionsDiv = this.suggestionsTarget;
    suggestionsDiv.innerHTML = "";
    if (results.length > 0) {
      results.forEach((result) => {
        const formattedAddress = this.formatAddress(result);
        const div = document.createElement("div");
        div.classList.add("suggestion");
        div.setAttribute("data-address-search-target", "interventionItem");
        div.setAttribute("data-action", "click->address-search#setAddress");
        div.setAttribute("data-id", "-1");
        div.innerHTML = formattedAddress;
        setTimeout(() => {
          div.onclick = () => this.selectSuggestion(result);
        }, 100);
        suggestionsDiv.appendChild(div);
      });
      suggestionsDiv.style.display = "block";
    } else {
      this.clearSuggestions();
    }
  }
  formatAddress(result) {
    const address = result.address;
    const street = address.road || "";
    const houseNumber = address.house_number || "";
    const city = address.city || address.town || address.village || "";
    const postalCode = address.postcode || "";
    const country = address.country || "";
    return `${houseNumber} ${street}, ${postalCode} ${city}, ${country}`;
  }
  setAddress(event) {
    this.inputTarget.value = event.target.innerText;
    this.addressTarget.value = event.target.innerText;
    this.interventionTarget.value = event.target.dataset.id;
  }
  selectSuggestion(result) {
    this.inputTarget.value = this.formatAddress(result);
    this.clearSuggestions();
    const divElement = document.createElement("div");
    divElement.classList.add("intervention-item");
    divElement.setAttribute("data-address-search-target", "interventionItem");
    divElement.setAttribute("data-action", "click->address-search#setAddress");
    divElement.setAttribute("data-id", `-1`);
    divElement.innerText = this.formatAddress(result);
    this.interventionListTarget.append(divElement);
    this.interventionListTarget.value = -1;
  }
  clearSuggestions() {
    this.suggestionsTarget.innerHTML = "";
    this.suggestionsTarget.style.display = "none";
  }
};

// app/javascript/controllers/base_finance_controller.js
var base_finance_controller_default = class extends Controller {
  static targets = ["itemsContainer"];
  // Common methods used by both controllers [FinanceController and FinanceItemController]
  showTotalPricePerLine() {
    const checkbox = document.querySelector("input[type='checkbox'][id$='_display_total_with_tax']");
    const displayClass = checkbox.checked ? "remove" : "add";
    document.querySelectorAll(".prices-pretax").forEach((element) => {
      element.classList[displayClass]("d-none");
    });
  }
  changeOrder() {
    const items = this.getVisibleItems();
    items.forEach((element, index2) => {
      const orderElement = element.querySelector(".order-count");
      if (orderElement) {
        element.querySelector("input[id*='order']").value = index2;
        orderElement.textContent = index2 + 1;
      }
    });
  }
  updateSummaryPrice() {
    const {
      quoteReduction,
      quoteReductionUnit,
      hasReduction
    } = this.getReductionValues();
    const sum = this.calculateSum();
    const tax = parseFloat((sum * 0.2).toFixed(2));
    const reduction = this.calculateReduction(sum, quoteReduction, quoteReductionUnit, hasReduction);
    const total = parseFloat((sum + tax - reduction).toFixed(2));
    this.updatePriceElements(sum, tax, reduction, total);
  }
  // Helper methods
  getVisibleItems() {
    const items = this.hasItemsContainerTarget ? this.itemsContainerTarget.querySelectorAll(".cover-quote-item") : document.querySelectorAll(".cover-quote-item");
    return Array.from(items).filter((item) => item.style.display !== "none");
  }
  getReductionValues() {
    return {
      quoteReduction: document.getElementById("quote_reduction")?.value || "0",
      quoteReductionUnit: document.getElementById("quote_reduction_unit")?.value || "currency",
      hasReduction: document.getElementById("quote_commercial_detail_attributes_display_global_discount")?.checked || false
    };
  }
  calculateSum() {
    return Array.from(document.querySelectorAll(".input-price-pretax")).reduce((acc, element) => acc + (parseFloat(element.value) || 0), 0);
  }
  calculateReduction(sum, quoteReduction, quoteReductionUnit, hasReduction) {
    if (!hasReduction) return 0;
    return quoteReductionUnit === "currency" ? parseFloat(quoteReduction) || 0 : parseFloat(sum * quoteReduction / 100);
  }
  updatePriceElements(sum, tax, reduction, total) {
    const elements = {
      leftTotalTax: document.getElementById("left-total-tax"),
      leftPricePretax: document.getElementById("left-prcie-pretax"),
      rightPricePretax: document.getElementById("right-price-pretax"),
      rightTotalTax: document.getElementById("right-total-tax"),
      rightTotalPrice: document.getElementById("right-total-prcie"),
      rightGlobalReduction: document.getElementById("right-global-reduction")
    };
    if (elements.leftTotalTax) elements.leftTotalTax.innerHTML = `${tax}\u20AC`;
    if (elements.leftPricePretax) elements.leftPricePretax.innerHTML = `${sum.toFixed(2)}\u20AC`;
    if (elements.rightGlobalReduction) elements.rightGlobalReduction.innerHTML = `${reduction.toFixed(2)}\u20AC`;
    if (elements.rightTotalTax) elements.rightTotalTax.innerHTML = `${tax}\u20AC`;
    if (elements.rightPricePretax) elements.rightPricePretax.innerHTML = `${sum.toFixed(2)}\u20AC`;
    if (elements.rightTotalPrice) elements.rightTotalPrice.innerHTML = `${total}\u20AC`;
  }
};

// app/javascript/controllers/boards_controller.js
var boards_controller_default = class extends Controller {
  static targets = ["boardsList"];
  connect() {
  }
  loadBoard(event) {
    event.preventDefault();
    const id = event.target.value;
    if (id != "") {
      fetch(`/boards/${id}`, {
        headers: {
          Accept: "text/vnd.turbo-stream.html"
        }
      }).then((response) => response.text()).then((html) => Turbo.renderStreamMessage(html));
    }
  }
  showModal(event) {
    event.preventDefault();
    const url = event.target.getAttribute("href");
    if (url != null) {
      fetch(url, {
        headers: {
          Accept: "text/vnd.turbo-stream.html"
        }
      }).then((response) => response.text()).then((html) => Turbo.renderStreamMessage(html));
    }
  }
};

// app/javascript/controllers/bs_modal_controller.js
var bs_modal_controller_default = class extends Controller {
  connect() {
    this.modal = new bootstrap.Modal(this.element, {
      keyboard: false
    });
    this.modal.show();
    this.element.addEventListener("hidden.bs.modal", this.removeModal.bind(this));
  }
  disconnect() {
    this.modal.hide();
  }
  submitEnd(event) {
    this.modal.hide();
  }
  removeModal() {
    this.element.remove();
  }
};

// app/javascript/controllers/client_controller.js
var client_controller_default = class extends Controller {
  static targets = ["company", "address", "city", "postal_code", "country", "suggestions", "errorFields"];
  connect() {
    this.pappersData = [];
  }
  getCompany(event) {
    const companyName = event.target.value.trim();
    if (companyName.length < 3) {
      this.clearSuggestions();
      return;
    }
    const url = `https://suggestions.pappers.fr/v2?q=${encodeURIComponent(companyName)}`;
    fetch(url).then((response) => response.json()).then((data) => {
      if (data.resultats_nom_entreprise && data.resultats_nom_entreprise.length > 0) {
        this.pappersData = data;
        this.showSuggestions(data.resultats_nom_entreprise);
      } else {
        this.clearSuggestions();
        this.markFieldsAsError();
      }
    }).catch((error2) => {
      this.clearSuggestions();
      this.markFieldsAsError();
    });
  }
  showSuggestions(results) {
    this.suggestionsTarget.innerHTML = "";
    results.forEach((result) => {
      const suggestionElement = document.createElement("div");
      suggestionElement.className = "suggestion-item";
      suggestionElement.setAttribute("id", 0);
      suggestionElement.innerHTML = `${result.nom_entreprise} <br><i>${result.domaine_activite}</i>`;
      suggestionElement.addEventListener("click", () => this.fillFields(result));
      this.suggestionsTarget.appendChild(suggestionElement);
    });
    this.suggestionsTarget.classList.remove("d-none");
  }
  fillFields(data) {
    document.getElementById("client_name").value = data.nom_entreprise;
    this.addressTarget.value = data.siege.adresse_ligne_1 || "";
    this.cityTarget.value = data.siege.ville || "";
    this.postal_codeTarget.value = data.siege.code_postal || "";
    this.countryTarget.value = data.siege.pays || "France";
    this.clearErrorState();
    this.clearSuggestions();
  }
  clearSuggestions() {
    this.suggestionsTarget.innerHTML = "";
    this.suggestionsTarget.classList.add("d-none");
  }
  markFieldsAsError() {
    this.errorFieldsTargets.forEach((field) => {
      if (!field.value.trim()) {
        field.classList.add("error");
      } else {
        field.classList.remove("error");
      }
    });
  }
  clearErrorState() {
    this.errorFieldsTargets.forEach((field) => {
      field.classList.remove("error");
    });
  }
};

