// app/javascript/controllers/finance_item_controller.js
var finance_item_controller_default = class extends base_finance_controller_default {
  static targets = [
    "quantity",
    "unitPrice",
    "unity",
    "days",
    "reduction",
    "reductionUnit",
    "pricePretax",
    "inputPricePretax",
    "hasDescription",
    "hasReduction"
  ];
  connect() {
    this.updateInputNames();
    this.changeOrder();
    this.updatePrice();
    this.updateSummaryPrice();
    this.showTotalPricePerLine();
    this.initTomSelect();
  }
  updatePrice(event) {
    const quantity = parseFloat(this.quantityTarget.value) || 0;
    const unitPrice = parseFloat(this.unitPriceTarget.value) || 0;
    const days = parseFloat(this.daysTarget.value) || 1;
    let pricePretax = quantity * unitPrice * days;
    if (this.hasReductionTarget.checked) {
      const reduction = parseFloat(this.reductionTarget.value) || 0;
      pricePretax = this.reductionUnitTarget.value === "currency" ? pricePretax - reduction : pricePretax - pricePretax * reduction / 100;
    }
    pricePretax = parseFloat(pricePretax.toFixed(2));
    this.pricePretaxTarget.innerHTML = `${pricePretax}\u20AC`;
    this.inputPricePretaxTarget.value = pricePretax;
    this.updateSummaryPrice();
  }
  showReduction(event) {
    this.reductionTarget.disabled = !event.target.checked;
    this.reductionUnitTarget.disabled = !event.target.checked;
  }
  updateInputNames() {
    document.querySelectorAll(".cover-quote-item").forEach((item, index2) => {
      item.setAttribute("id", `quote-item-${index2}`);
      item.querySelectorAll("input, select, textarea").forEach((input) => {
        input.name = input.name.replace(/__INDEX__/, index2);
        input.id = input.id.replace(/__INDEX__/, index2);
      });
      const orderElement = item.querySelector(".order-count");
      if (orderElement) {
        orderElement.textContent = index2 + 1;
      }
    });
  }
  initTomSelect() {
    if (!this.hasUnityTarget || this.unityTarget.tomselect) return;
    new tom_select_complete_default(this.unityTarget, {
      create: true,
      createOnBlur: true,
      render: {
        option_create: (data, escape) => `<div class="create">Ajouter <strong>${escape(data.input)}</strong>&hellip;</div>`,
        no_results: () => '<div class="no-results">Aucun r\xE9sultat trouv\xE9</div>'
      }
    });
  }
};

