// app/javascript/controllers/multi_select_controller.js
var multi_select_controller_default = class extends Controller {
  static targets = ["input", "toggleAll", "option", "toggleAllLabel"];
  updateSelection() {
    const checkboxes = this.element.querySelectorAll("input[type='checkbox']:not([data-multi-select-target='toggleAll'])");
    const selectedCount = [...checkboxes].filter((checkbox) => checkbox.checked).length;
    this.inputTarget.value = `${selectedCount} s\xE9lectionn\xE9(s)`;
    this.toggleAllTarget.checked = selectedCount === checkboxes.length;
    selectedCount === checkboxes.length ? this.toggleAllLabelTarget.innerText = "Tout d\xE9s\xE9lectionner" : this.toggleAllLabelTarget.innerText = "Tout s\xE9lectionner";
  }
  toggleAll(event) {
    const checkboxes = this.element.querySelectorAll("input[type='checkbox']:not([data-multi-select-target='toggleAll'])");
    const shouldCheck = event.target.checked;
    checkboxes.forEach((checkbox) => {
      checkbox.checked = shouldCheck;
    });
    if (shouldCheck) {
      this.toggleAllLabelTarget.innerText = "Tout d\xE9s\xE9lectionner";
    } else {
      this.toggleAllLabelTarget.innerText = "Tout s\xE9lectionner";
    }
    this.inputTarget.value = shouldCheck ? `${checkboxes.length} s\xE9lectionn\xE9(s)` : "0 s\xE9lectionn\xE9(s)";
  }
  search(event) {
    const query = event.target.value.toLowerCase();
    this.optionTargets.forEach((option2) => {
      const text = option2.innerText.toLowerCase();
      option2.style.display = text.includes(query) ? "block" : "none";
    });
  }
};

// app/javascript/controllers/needs_agents_controller.js
var needs_agents_controller_default = class extends Controller {
  static targets = ["agentID"];
  connect() {
    this.agentsListTarget = document.querySelector("input[data-name='agentsList']");
    setTimeout(() => {
      this.syncCheckedState();
    }, 200);
  }
  syncCheckedState() {
    const agentsList = JSON.parse(this.agentsListTarget.value || "[]");
    const checkboxes = this.element.querySelectorAll("input[data-action*='toggleAgentID']");
    checkboxes.forEach((checkbox) => {
      checkbox.checked = agentsList.includes(checkbox.value);
    });
  }
  toggleAgentID(event) {
    const agentID = event.target.value;
    let agentsList = JSON.parse(this.agentsListTarget.value || "[]");
    if (event.target.checked) {
      if (!agentsList.includes(agentID)) agentsList.push(agentID);
    } else {
      agentsList = agentsList.filter((id) => id !== agentID);
    }
    this.agentsListTarget.value = JSON.stringify(agentsList);
  }
  clearAgentsList() {
    document.querySelector("input[data-name='agentsList']").value = "";
  }
  disconnect() {
  }
};

